mapper.insert:
INSERT INTO video_play_segment (segment_id, session_id, segment, create_time, update_time)
VALUES (#{id.segmentId}, #{id.sessionId}, int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds}), #{createTime}, #{updateTime})
ON CONFLICT (session_id, segment_id)
DO UPDATE SET segment = int4range(lower(video_play_segment.segment), #{endWatchTimeInSeconds}), update_time = #{updateTime}
    WHERE NOT video_play_segment.segment @> int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds});

mapper.select:
SELECT time_bucket, SUM(upper(segment) - lower(segment)) AS value
FROM video_play_segment play_segment
    JOIN video_play_session play_session
        ON play_session.id = play_segment.session_id AND play_session.master_id = #{masterId}

                AND play_session.video_id IN

                    #{videoId}



            JOIN gc_video video ON play_session.video_id = video.id
            JOIN sys_file video_file ON video.file_id = video_file.id
            JOIN gc_user_access user_content_group ON user_content_group.user_id = video_file.upload_uid AND user_content_group.master_id = #{masterId}
                AND user_content_group.access_id IN

                    #{contentGroupId}


    RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket
        ON play_segment.update_time >= time_bucket AND play_segment.update_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket
ORDER BY time_bucket;

SELECT video.id AS videoId, SUM(upper(play_segement.segment) - lower(play_segement.segment)) AS value
FROM gc_video video
    LEFT JOIN video_play_session play_session ON play_session.video_id = video.id
        AND play_session.create_time >= #{filter.start}
        AND play_session.create_time < #{filter.end}
        AND play_session.master_id = #{masterId}
    LEFT JOIN video_play_segment play_segement ON play_segement.session_id = play_session.id

    WHERE video.id IN

        #{videoId}


GROUP BY video.id;

SELECT time_bucket, SUM(upper(play_segment.segment) - lower(play_segment.segment)) / COUNT(play_session.id)::double precision AS value
FROM video_play_segment play_segment
    JOIN video_play_session play_session
        ON play_session.id = play_segment.session_id AND play_session.master_id = #{masterId}

                AND play_session.video_id IN

                    #{videoId}



        JOIN gc_video video ON play_session.video_id = video.id
        JOIN sys_file video_file ON video.file_id = video_file.id
        JOIN gc_user_access user_content_group ON user_content_group.user_id = video_file.upload_uid AND user_content_group.master_id = #{masterId}
        AND user_content_group.access_id IN

            #{contentGroupId}


    RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket
            ON play_session.update_time >= time_bucket AND play_session.update_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket
ORDER BY time_bucket;

SELECT time_bucket, AVG(ratio) AS value FROM ( SELECT time_bucket, CASE WHEN COUNT(engagement_rate) OVER (PARTITION BY time_bucket) = 0 THEN 0 ELSE COUNT(engagement_rate) FILTER (WHERE engagement_rate < #{dropOffThreshold} AND engagement_rate != 0.0) OVER (PARTITION BY time_bucket) / COUNT(engagement_rate) OVER (PARTITION BY time_bucket)::double precision END AS ratio FROM ( SELECT time_bucket, SUM(upper(segment) - LOWER(segment)) / SUM(video_time)::double precision AS engagement_rate FROM video_play_segment play_segment JOIN video_play_session play_session ON play_session.id = play_segment.session_id AND play_session.master_id = #{masterId} JOIN gc_video video ON play_session.video_id = video.id AND video.video_time != 0
AND video.id IN
#{videoId}
JOIN sys_file video_file ON video.file_id = video_file.id JOIN gc_user_access user_content_group ON user_content_group.user_id = video_file.upload_uid AND user_content_group.master_id = #{masterId} AND user_content_group.access_id IN
#{contentGroupId}
RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket ON play_session.update_time >= time_bucket AND play_session.update_time < time_bucket + concat(#{filter.step}, ' second')::interval GROUP BY time_bucket, play_segment.session_id ORDER BY time_bucket ) AS engagement ) AS drop_off GROUP BY time_bucket ORDER BY time_bucket;

SELECT videoId AS videoId, AVG(ratio) AS value
FROM (
    SELECT engagement.videoId as videoId,
        CASE
            WHEN COUNT(engagement_rate) OVER (PARTITION BY engagement.videoId) = 0 THEN 0
            ELSE COUNT(engagement_rate) FILTER (WHERE engagement_rate < #{dropOffThreshold} AND engagement_rate != 0.0) OVER (PARTITION BY engagement.videoId) / COUNT(engagement_rate) OVER (PARTITION BY engagement.videoId)::double precision
        END AS ratio
    FROM (
        SELECT video.id as videoId,
            SUM(upper(segment) - LOWER(segment)) / SUM(video.video_time)::double precision AS engagement_rate
        FROM gc_video video
            LEFT JOIN video_play_session play_session ON play_session.video_id = video.id
                AND play_session.create_time >= #{filter.start}
                AND play_session.create_time < #{filter.end}
                AND play_session.master_id = #{masterId}
            LEFT JOIN video_play_segment play_segement ON play_segement.session_id = play_session.id
        WHERE video.video_time != 0

            AND video.id IN

                #{videoId}


        GROUP BY video.id
) AS engagement
) AS drop_off
GROUP BY drop_off.videoId;

SELECT time_bucket,
    SUM(upper(segment) - LOWER(segment)) / SUM(video_time)::double precision AS value
FROM video_play_segment play_segment
    JOIN video_play_session play_session
        ON play_session.id = play_segment.session_id AND play_session.master_id = #{masterId}
    JOIN gc_video video ON play_session.video_id = video.id AND video.video_time != 0

            AND video.id IN

                #{videoId}



        JOIN sys_file video_file ON video.file_id = video_file.id
        JOIN gc_user_access user_content_group ON user_content_group.user_id = video_file.upload_uid AND user_content_group.master_id = #{masterId}
        AND user_content_group.access_id IN

            #{contentGroupId}



    RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket
            ON play_segment.update_time >= time_bucket AND play_segment.update_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket
ORDER BY time_bucket;

SELECT video.id AS videoId,
    SUM(upper(segment) - LOWER(segment)) / SUM(video.video_time)::double precision AS value
FROM gc_video video
    LEFT JOIN video_play_session play_session ON play_session.video_id = video.id
        AND play_session.create_time >= #{filter.start}
        AND play_session.create_time < #{filter.end}
        AND play_session.master_id = #{masterId}
    LEFT JOIN video_play_segment play_segement ON play_segement.session_id = play_session.id
WHERE video.video_time != 0

    AND video.id IN

        #{videoId}


GROUP BY video.id;
